-- ADM-08 · Bug reports from any approved user, with screenshots
-- (contracts/schema.md, contracts/permissions.md `bug:report` / `bug:triage`; REQ-ADM-03)
--
-- Tables, the enum and the indexes below were generated by drizzle-kit from
-- db/schema/bugs.ts; the updated_at trigger and RLS are appended by hand.
--
-- Deploy safety: this migration only adds things (one enum, two tables, two indexes, one
-- trigger function, policies on the new tables). Nothing the live build reads or writes
-- changes, so it is safe to apply while that build is serving.
--
-- Storage: screenshots go in ADM-06's private `admin-attachments` bucket under
-- bugs/{report_id}/{image_id}.{ext}. Uploads use server-issued signed URLs and reads use
-- signed URLs, so the bucket's admin-only policies (0006) stay as they are.

CREATE TYPE "public"."bug_report_status" AS ENUM('new', 'confirmed', 'fixed', 'wont_fix', 'duplicate');--> statement-breakpoint
CREATE TABLE "bug_report_images" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"report_id" uuid NOT NULL,
	"storage_path" text NOT NULL,
	"file_name" text NOT NULL,
	"mime_type" text NOT NULL,
	"size_bytes" integer NOT NULL,
	"created_by" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "bug_report_images_storage_path_key" UNIQUE("storage_path"),
	CONSTRAINT "bug_report_images_mime_type_check" CHECK ("bug_report_images"."mime_type" in ('image/png','image/jpeg','image/webp','image/gif')),
	CONSTRAINT "bug_report_images_size_bytes_check" CHECK ("bug_report_images"."size_bytes" between 1 and 10485760)
);
