CREATE TABLE "bug_reports" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"title" text NOT NULL,
	"description" text NOT NULL,
	"expected" text,
	"page_path" text,
	"user_agent" text,
	"viewport" text,
	"app_version" text,
	"status" "bug_report_status" DEFAULT 'new' NOT NULL,
	"admin_note" text,
	"created_by" uuid NOT NULL,
