	CONSTRAINT "bug_reports_page_path_check" CHECK ("bug_reports"."page_path" ~ '^/' and char_length("bug_reports"."page_path") <= 2000),
	CONSTRAINT "bug_reports_user_agent_check" CHECK (char_length("bug_reports"."user_agent") <= 1000),
	CONSTRAINT "bug_reports_viewport_check" CHECK (char_length("bug_reports"."viewport") <= 40),
	CONSTRAINT "bug_reports_admin_note_check" CHECK (char_length("bug_reports"."admin_note") <= 2000)
);
