-- ---------------------------------------------------------------------------
-- updated_at: stamped on every update of a report.
-- ---------------------------------------------------------------------------
create or replace function public.bug_reports_touch_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $fn$
begin
  new.updated_at := pg_catalog.now();
  return new;
end;
$fn$;
--> statement-breakpoint
create trigger bug_reports_touch_updated_at
  before update on public.bug_reports
  for each row execute function public.bug_reports_touch_updated_at();
--> statement-breakpoint

-- ---------------------------------------------------------------------------
-- RLS. app_role_at_least('member') is true only for approved, active users
-- (0004), so pending, rejected and disabled users get nothing. Policies bind
-- `authenticated` only, so `anon` gets nothing. Server code (postgres /
-- service_role, BYPASSRLS) authorizes with assertCan first.
--
-- bug_reports (bug:report / bug:triage):
--   insert: an approved user, as themselves;
--   select: your own rows, or every row for an admin;
--   update / delete: admins only.
-- bug_report_images:
--   select: follows the report (the subquery runs under bug_reports' RLS);
--   insert: the report's creator, as themselves, within 24 h of the report;
--   delete: admins only. No update.
-- ---------------------------------------------------------------------------
alter table public.bug_reports       enable row level security;
--> statement-breakpoint
alter table public.bug_report_images enable row level security;
--> statement-breakpoint
revoke truncate, trigger, references on public.bug_reports, public.bug_report_images
  from anon, authenticated;
--> statement-breakpoint
create policy bug_reports_insert on public.bug_reports for insert to authenticated
  with check (
    (select public.app_role_at_least('member'))
    and created_by = (select auth.uid())
  );
--> statement-breakpoint
create policy bug_reports_select on public.bug_reports for select to authenticated
  using (
    (select public.app_role_at_least('admin'))
    or ((select public.app_role_at_least('member')) and created_by = (select auth.uid()))
  );
--> statement-breakpoint
create policy bug_reports_update on public.bug_reports for update to authenticated
  using ((select public.app_role_at_least('admin')))
  with check ((select public.app_role_at_least('admin')));
--> statement-breakpoint
create policy bug_reports_delete on public.bug_reports for delete to authenticated
  using ((select public.app_role_at_least('admin')));
--> statement-breakpoint
create policy bug_report_images_select on public.bug_report_images for select to authenticated
  using (exists (select 1 from public.bug_reports r where r.id = report_id));
--> statement-breakpoint
create policy bug_report_images_insert on public.bug_report_images for insert to authenticated
  with check (
    (select public.app_role_at_least('member'))
    and created_by = (select auth.uid())
    and exists (
      select 1 from public.bug_reports r
      where r.id = report_id
        and r.created_by = (select auth.uid())
        and r.created_at > pg_catalog.now() - interval '24 hours'
    )
  );
--> statement-breakpoint
create policy bug_report_images_delete on public.bug_report_images for delete to authenticated
  using ((select public.app_role_at_least('admin')));
